describe('Session storage', () => {
  let testDir: string;

  beforeEach(async () => {
    testDir = await fs.mkdtemp(path.join(os.tmpdir(), 'kspec-session-test-'));
  });

  afterEach(async () => {
    await fs.rm(testDir, { recursive: true });
  });

